import{_ as t,c as a,o as l,a1 as r}from"./chunks/framework.C3Hmo1as.js";const g=JSON.parse('{"title":"AI 和生产力","description":null,"frontmatter":{"title":"AI 和生产力","description":null,"date":"2026-04-28T00:00:00.000Z","tags":[]},"headers":[],"relativePath":"think/ai-and-productivity.md","filePath":"think/ai-and-productivity.md"}'),e={name:"think/ai-and-productivity.md"};function o(n,i,s,u,d,h){return l(),a("div",null,[...i[0]||(i[0]=[r('<blockquote><ul><li>颠覆性技术创造的巨大红利，从来不来自于技术本身对旧工具的直接替换，而来自于围绕新技术对“生产关系和组织流程”的彻底重构。</li><li>斯坦福大学经济学家保罗·大卫（Paul David）在 1990 年发表的经典论文《发电机与计算机》（The Dynamo and the Computer）中提出了一个观点。他用电力的发展史来解释为什么新技术出现初期，宏观经济数据上往往看不到生产率的提升（即所谓的“生产力悖论”）。</li></ul></blockquote><h2 id="新技术的出现未必会带来生产力的显著提升" tabindex="-1">新技术的出现未必会带来生产力的显著提升 <a class="header-anchor" href="#新技术的出现未必会带来生产力的显著提升" aria-label="Permalink to &quot;新技术的出现未必会带来生产力的显著提升&quot;">​</a></h2><ul><li>电力发明之后，整整 20 到 30 年企业效率没有提高。</li><li>因为大家&quot;用法不对&quot;，只是把电机替换原来的蒸汽机，没有重组生产流程。</li><li>直到福特把自动化生产线发明出来，电力才真正重塑了工业，也才催生了 30 年代的大萧条。</li></ul><h3 id="_1-蒸汽时代的-集中式动力-group-drive" tabindex="-1">1. 蒸汽时代的“集中式动力” (Group Drive) <a class="header-anchor" href="#_1-蒸汽时代的-集中式动力-group-drive" aria-label="Permalink to &quot;1. 蒸汽时代的“集中式动力” (Group Drive)&quot;">​</a></h3><p>在电力普及之前，工厂使用的是蒸汽机。蒸汽机的特点是**“单点集中发力”**。</p><ul><li>工厂的地下室或核心区域有一台巨大的蒸汽机，它转动一根贯穿整个工厂的主传动轴。</li><li>所有的车床、织布机等设备，都要通过复杂的齿轮、天车和长长的皮带连接到这根主轴上获取动力。</li><li><strong>致命限制：</strong> 机器的摆放位置不能根据“生产流程”来定，而是必须根据**“离动力轴有多近”**来定。为了充分利用动力，工厂通常被建造成拥挤的多层楼房，物料在楼层间搬上搬下，极其低效。一旦主蒸汽机发生故障，整个工厂的机器都得停工。</li></ul><h3 id="_2-电力初期的-平替式误用-单纯替换动力源" tabindex="-1">2. 电力初期的“平替式误用” (单纯替换动力源) <a class="header-anchor" href="#_2-电力初期的-平替式误用-单纯替换动力源" aria-label="Permalink to &quot;2. 电力初期的“平替式误用” (单纯替换动力源)&quot;">​</a></h3><p>19 世纪末（1880-1890年代），电动机开始进入工厂。但当时的资本家和工程师是怎么用电的呢？</p><ul><li>他们仅仅是<strong>把地下室的那台大蒸汽机，换成了一台巨大的电动机</strong>。</li><li>厂房的结构没有变，复杂的传动轴没有变，满天飞的皮带没有变，机器的拥挤摆放也没有变。</li><li><strong>结果：</strong> 企业的生产流程并没有被优化。虽然电力比蒸汽机稍微清洁和稳定一点，但为了引入电力系统，企业花费了巨额的初始投资，反而短期内拖累了投资回报率（ROI）。这就是为什么在长达 20-30 年的时间里（直到 1910 年代），宏观统计上的“企业生产效率”不仅没有大涨，甚至一度停滞。</li></ul><h3 id="_3-范式转移与-流程重组-unit-drive-分布式动力" tabindex="-1">3. 范式转移与“流程重组” (Unit Drive / 分布式动力) <a class="header-anchor" href="#_3-范式转移与-流程重组-unit-drive-分布式动力" aria-label="Permalink to &quot;3. 范式转移与“流程重组” (Unit Drive / 分布式动力)&quot;">​</a></h3><p>直到 20 世纪 10 年代末到 20 年代，新一代的工程师和管理者才真正理解了电力的本质优势：<strong>电力是可以被分割和无限传输的。</strong></p><ul><li>工厂开始抛弃巨大的中央电动机和复杂的皮带，转而<strong>给每一台机器安装一个独立的小型电动机（Unit Drive）</strong>。</li><li><strong>真正的革命发生了：</strong> 机器彻底摆脱了动力轴的束缚！现在，机器可以完全按照**“零部件加工的先后顺序”**来排列。</li><li>工厂的物理形态被重塑：多层楼的拥挤厂房被废弃，取而代之的是占地面积巨大的<strong>单层大平层工厂</strong>。物料可以沿着一条直线顺畅地从头走到尾——<strong>这直接催生了亨利·福特的“流水线生产”</strong>。</li><li>直到这一刻，企业的生产效率才迎来了成倍的爆发式增长。</li></ul><h2 id="ai-时代的类比" tabindex="-1">AI 时代的类比 <a class="header-anchor" href="#ai-时代的类比" aria-label="Permalink to &quot;AI 时代的类比&quot;">​</a></h2><ul><li>软件市场只有 1 万亿，劳动力市场是 80 万亿。</li><li>AI 不是上一轮互联网的延续，而像电力时代 —— 它要重写的是全部的人力分工！</li><li>我们正处于 AI 大规模自动化“人类工作”的萌芽期，后面还有很多动荡的情节等待发生。</li></ul><h3 id="对-ai-周期的启示" tabindex="-1">对 AI 周期的启示 <a class="header-anchor" href="#对-ai-周期的启示" aria-label="Permalink to &quot;对 AI 周期的启示&quot;">​</a></h3><ul><li><strong>现在的 AI 用法 = 刚换上大型电动机的工厂。</strong> 我们现在大多是在做“平替”。比如用 AI 帮现有的程序员写代码快一点，帮营销人员写文案快一点，帮律师查资料快一点。这只是在原有的“人类工作流”和“企业组织架构”上打补丁，本质上是在“加速旧流程”。</li><li><strong>未来的 AI 爆发 = 为每台机器装上小马达 + 重组流水线。</strong> 当 AI 真正重塑企业效率时，它将改变公司的组织架构。比如，以前一个软件公司需要“产品经理提需求 -&gt; 设计师出图 -&gt; 程序员写代码 -&gt; 测试员测试”的线状协作流程；未来可能变成“一个超级节点人类 + 多个互相交互的 AI Agent”，整个部门的协作方式和人力分工被彻底重写。</li></ul>',16)])])}const _=t(e,[["render",o]]);export{g as __pageData,_ as default};
